        if digest(&manifest_bytes) != publication.manifest_sha256 { return Err(data_error("sealed capture changed before publication")); }
        if load.is_some_and(|load| load.ingestion_key.uuid() != publication.run) { return Err(data_error("projection belongs to another capture")); }
